with kept_keys as (select status, id from shipments intersect select status, id from shipments where order_id = 22), verified as (select s.* from shipments s join kept_keys k on s.status = k.status and s.id = k.id) select order_id, shipped_date, delivered_date, status, case when status rlike '^(RETURNED|IN_TRANSIT)$' then 'PRIORITY' else 'EXTENDED' end as status_zone from verified order by status_zone desc nulls last;
